"%% model.m — Robust stability margins of a designed loop (margin_02)
% L(s) = 9 / (s^3 + 5 s^2 + 6 s) = 9 / (s (s+2)(s+3))  (type-1 loop)
% Compute classical gain and phase margins via Control System Toolbox
% margin(), then write result.json.

clear; clc;

% --- Loop transfer function (descending powers) ---
num = [9.0];
den = [1.0, 5.0, 6.0, 0.0];
L   = tf(num, den);

% --- Classical stability margins ---
% [Gm, Pm, Wcg, Wcp] = margin(L):
%   Gm  = linear gain margin
%   Pm  = phase margin (deg)
%   Wcg = frequency where phase crosses -180 deg (phase crossover, rad/s)
%   Wcp = frequency where gain crosses 0 dB   (gain crossover, rad/s)
[Gm, Pm, Wcg, Wcp] = margin(L);

% --- Assemble output struct ---
result = struct();
result.gm_db  = 20 * log10(Gm);  % gain margin in dB
result.pm_deg = Pm;              % phase margin in degrees
result.w_gc   = Wcp;             % gain crossover frequency (rad/s)
result.w_pc   = Wcg;             % phase crossover frequency (rad/s)

% --- Write result.json (jsonencode of top-level struct) ---
jsonStr = jsonencode(result);
fid = fopen('result.json', 'w');
if fid == -1
    error('model:FileOpen', 'Unable to open result.json for writing.');
end
fwrite(fid, jsonStr, 'char');
fclose(fid);

% --- Report to console ---
fprintf('Loop: L(s) = 9 / (s^3 + 5 s^2 + 6 s)\n');
fprintf('Gain margin        gm_db  = %.6f dB   (linear Gm = %.6f)\n', result.gm_db, Gm);
fprintf('Phase margin       pm_deg = %.6f deg\n', result.pm_deg);
fprintf('Gain crossover     w_gc   = %.6f rad/s\n', result.w_gc);
fprintf('Phase crossover    w_pc   = %.6f rad/s\n', result.w_pc);
fprintf('result.json written.\n');"
